Here’s a small, self-contained app using Python’s standard library and SQLite. Signups are stored persistently, and a database transaction prevents concurrent requests from exceeding 20 seats.

Save as `app.py`:

```python
import json
import re
import sqlite3
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

DB = "workshop.db"
CAPACITY = 20

HTML = """<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Workshop signup</title>
  <style>
    body { font: 16px system-ui, sans-serif; background: #f3f5fa; color: #182033;
           margin: 0; padding: 3rem 1rem; }
    main { max-width: 420px; margin: auto; padding: 2rem; background: white;
           border-radius: 12px; box-shadow: 0 4px 24px #0001; }
    label { display: block; margin: 1rem 0 .35rem; font-weight: 600; }
    input { box-sizing: border-box; width: 100%; padding: .7rem; border: 1px solid #aab;
            border-radius: 6px; font: inherit; }
    button { margin-top: 1.25rem; width: 100%; padding: .75rem; border: 0;
             border-radius: 6px; background: #3456d1; color: white;
             font: inherit; cursor: pointer; }
    button:disabled { background: #889; cursor: not-allowed; }
    #message { min-height: 1.5em; }
  </style>
</head>
<body>
  <main>
    <h1>Workshop signup</h1>
    <p id="availability">Checking availability…</p>
    <form id="signup">
      <label for="name">Name</label>
      <input id="name" name="name" maxlength="100" required autocomplete="name">
      <label for="email">Email</label>
      <input id="email" name="email" type="email" maxlength="254" required autocomplete="email">
      <button id="submit" type="submit">Reserve a seat</button>
    </form>
    <p id="message" role="status" aria-live="polite"></p>
  </main>
  <script>
    const form = document.querySelector('#signup');
    const button = document.querySelector('#submit');
    const availability = document.querySelector('#availability');
    const message = document.querySelector('#message');

    function showSeats(count) {
      availability.textContent = count === 0
        ? 'This workshop is full.'
        : `${count} of 20 seats available.`;
      button.disabled = count === 0;
    }

    async function refreshSeats() {
      try {
        const response = await fetch('/seats');
        if (!response.ok) throw new Error();
        showSeats((await response.json()).remaining);
      } catch {
        availability.textContent = 'Could not check availability. Please refresh.';
      }
    }

    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      button.disabled = true;
      message.textContent = 'Reserving…';
      try {
        const response = await fetch('/signup', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            name: form.elements.name.value,
            email: form.elements.email.value
          })
        });
        const result = await response.json();
        message.textContent = result.message;
        if (response.ok) form.reset();
      } catch {
        message.textContent = 'Could not submit. Please try again.';
      }
      button.disabled = false;
      await refreshSeats();
    });

    refreshSeats();
  </script>
</body>
</html>"""


def connect():
    return sqlite3.connect(DB, timeout=10)


with connect() as db:
    db.execute("""
        CREATE TABLE IF NOT EXISTS signups (
            id INTEGER PRIMARY KEY,
            name TEXT NOT NULL,
            email TEXT NOT NULL UNIQUE
        )
    """)


class Handler(BaseHTTPRequestHandler):
    def send_json(self, status, data):
        body = json.dumps(data).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        if self.path == "/":
            body = HTML.encode()
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
        elif self.path == "/seats":
            with connect() as db:
                count = db.execute("SELECT COUNT(*) FROM signups").fetchone()[0]
            self.send_json(200, {"remaining": max(0, CAPACITY - count)})
        else:
            self.send_error(404)

    def do_POST(self):
        if self.path != "/signup":
            self.send_error(404)
            return

        try:
            length = int(self.headers.get("Content-Length", "0"))
            if not 0 < length <= 4096:
                raise ValueError()
            data = json.loads(self.rfile.read(length))
            name = data["name"].strip()
            email = data["email"].strip().lower()
            if (not name or len(name) > 100 or len(email) > 254
                    or not re.fullmatch(r"[^\\s@]+@[^\\s@]+\\.[^\\s@]+", email)):
                raise ValueError()
        except (ValueError, KeyError, TypeError, AttributeError):
            self.send_json(400, {"message": "Please enter a valid name and email."})
            return

        try:
            with connect() as db:
                # Acquire the write lock before checking capacity.
                db.execute("BEGIN IMMEDIATE")
                if db.execute(
                    "SELECT 1 FROM signups WHERE email = ?", (email,)
                ).fetchone():
                    self.send_json(409, {"message": "That email is already registered."})
                    return
                count = db.execute("SELECT COUNT(*) FROM signups").fetchone()[0]
                if count >= CAPACITY:
                    self.send_json(409, {"message": "Sorry, the workshop is full."})
                    return
                db.execute(
                    "INSERT INTO signups (name, email) VALUES (?, ?)", (name, email)
                )
            self.send_json(201, {"message": "You're registered! Your seat is reserved."})
        except sqlite3.Error:
            self.send_json(500, {"message": "Something went wrong. Please try again."})


if __name__ == "__main__":
    print("Open http://localhost:8000")
    ThreadingHTTPServer(("127.0.0.1", 8000), Handler).serve_forever()
```

Run it with `python3 app.py`, then open **http://localhost:8000**. Signups are saved in `workshop.db`. For public deployment, put the app behind HTTPS and add appropriate privacy and anti-abuse protections.

